    public static class ElsaMorante
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Che il segreto dell'arte sia qui? Ricordare come l'opera si è vista in uno stato di sogno, ridirla come si è vista, cercare soprattutto di ricordare. Ché forse tutto l'inventare è ricordare.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Grande civiltà di Napoli: la città più civile del mondo. La vera regina delle città, la più signorile, la più nobile. La sola vera metropoli italiana.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Lodiamo tutta la multiforme nazione dei nostri compagni animali, questo circo angelico in cui l'uomo può riconoscere, a testimonianza del suo rango perduto, la nobile infanzia dell'Eden.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Più di tutto al mondo amo i bambini, il mare e i gatti.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Solo chi ama conosce. Povero chi non ama!", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Una delle possibili definizioni giuste di scrittore, per me sarebbe addirittura la seguente: un uomo a cui sta a cuore tutto quanto accade, fuorché la letteratura.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "È strano come l'Eternità si lasci captare piuttosto in un segmento effimero che in una continuità estesa.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "La loro sola speranza, era di diventare le spose d'un eroe: di servirlo, di stemmarsi del suo nome, di essere la sua proprietà indivisa, che tutti rispettano; e di avere un bel figlio da lui, somigliante al padre.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Ma vivere senza nessun mestiere è la miglior cosa: magari accontentarsi di mangiare pane solo, purché non sia guadagnato.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Beh, il primo pensiero, il massimo di tutti, è questo: \"Non bisogna importarsene della morte!\"", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Impara: il sacrificio è la sola, vera perversione umana.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Almeno dalle altre femmine, uno può salvarsi, può scoraggiare il loro \"amore\"; ma dalla madre, chi ti salva?", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Ah, è un inferno essere amati da chi non ama né la felicità, né la vita, né se stesso, ma soltanto te!", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "L'amore vero è così: non ha nessuno scopo e nessuna ragione, e non si sottomette a nessun potere fuorché alla grazia umana.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Una speranza, a volte, indebolisce le coscienze, come un vizio.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "E così in eterno ogni perla del mare ricopia la prima perla, e ogni rosa ricopia la prima rosa.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "La speranza, tuttavia, s'era annidata ormai dentro di me come un parassita, che non lascia volentieri il suo nido.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "La sola ragione che ho avuta (di cui fossi consapevole) nel mettermi a raccontare la vita di Arturo, è stata (non rida) il mio antico e inguaribile desiderio di essere un ragazzo.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Le libertà non vengono date. Si prendono.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "La camera a gas è l'unico punto di carità, nel campo di concentramento.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Erano dei ciechi, guidati da ciechi e alla guida di altri ciechi, e non se ne accorgevano... Si ritenevano dei giusti – in perfetta buona fede! – e nessuno li smentiva in questo loro abbaglio.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Gli animali, come tutti i paria, sono talora ispirati da un genio quasi divino...", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "La Storia, si capisce, è tutta un'oscenità fino dal principio.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Si sa che la fabbrica dei sogni spesso interra le sue fondamenta fra i tritumi della veglia o del passato.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Sebbene io non abbia ancora vissuto un numero d'anni sufficiente per poterlo credere, sono quasi certa di essere stata io, quella ragazzina.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Chi fugge per amore non può trovar quiete nella solitudine.", Author = "Elsa Morante" },
        };
    }
